241	    private BigDecimal calculateBuy3Pay2Discount(List<CheckoutSummaryRequest.OrderItemRequest> items,
242	                                                 List<Product> products) {
243	        BigDecimal discount = BigDecimal.ZERO;
244	
245	        for (int i = 0; i < items.size(); i++) {
246	            long quantity = items.get(i).getQuantity();
247	            long freeItems = quantity / 3;
248	            if (freeItems > 0) {
249	                BigDecimal itemDiscount = CurrencyUtils.multiply(
250	                        products.get(i).getPrice(),
251	                        new BigDecimal(freeItems)
252	                );
253	                discount = CurrencyUtils.add(discount, itemDiscount);
254	            }
255	        }
256	
257	        return discount;
258	    }
