260	    private ShippingInfo calculateShipping(ShippingMethod method, String zipCode,
261	                                          List<CheckoutSummaryRequest.OrderItemRequest> items,
262	                                          List<Product> products, Region region) {
263	        BigDecimal totalWeight = calculateTotalWeight(items, products);
264	
265	        if (method == ShippingMethod.COURIER) {
266	            if (totalWeight.compareTo(new BigDecimal(MAX_COURIER_WEIGHT_KG)) > 0) {
267	                throw new OrderServiceException("SHIPPING_METHOD_UNAVAILABLE", "Courier does not support this weight", HttpStatus.UNPROCESSABLE_ENTITY);
268	            }
269	            return new ShippingInfo(COURIER_COST, COURIER_DELIVERY_DAYS);
270	        } else if (method == ShippingMethod.STORE_PICKUP) {
271	            return new ShippingInfo(BigDecimal.ZERO, STORE_PICKUP_DAYS);
272	        } else if (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS) {
273	            String service = method == ShippingMethod.ECONOMY ? "STD" : "EXP";
274	            int weightGrams = totalWeight.multiply(new BigDecimal("1000"))
275	                    .setScale(0, RoundingMode.DOWN).intValue();
276	
277	            Optional<TransLogClient.TransLogQuoteResponse> quote = transLogClient.getQuote(zipCode, weightGrams, service);
278	
279	            if (quote.isEmpty()) {
280	                throw new OrderServiceException("SHIPPING_METHOD_UNAVAILABLE",
281	                        "Shipping method not available for this location", HttpStatus.UNPROCESSABLE_ENTITY);
282	            }
283	
284	            TransLogClient.TransLogQuoteResponse response = quote.get();
285	            BigDecimal cost = new BigDecimal(response.getPriceCents()).divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
286	            int days = (int) Math.ceil(response.getEtaHours() / 24.0);
287	
288	            if (region == Region.NORTH) {
289	                days += NORTH_EXTRA_DAYS;
290	            } else if (region == Region.NORTHEAST) {
291	                days += NORTHEAST_EXTRA_DAYS;
292	            }
293	
294	            return new ShippingInfo(cost, days);
295	        }
296	
297	        throw new OrderServiceException("INVALID_SHIPPING_METHOD", "Invalid shipping method", HttpStatus.UNPROCESSABLE_ENTITY);
298	    }
